        "themeStudio.themeListLabel": "Interface theme",
        "themeStudio.modeGroupLabel": "Color mode",
        "themeStudio.stopPreview": "Stop preview",
        "themeStudio.notStated": "not stated",
        "themeStudio.resumePreview": "Resume preview",
        "themeStudio.theme.calm.scene": "Horizon and filament",
        "themeStudio.theme.calm.material": "Graphite / bronze",
        "themeStudio.theme.calm.text": "An almost still field, a horizon and a single bronze filament. The emptiness remains part of the composition.",
        "themeStudio.theme.forge.scene": "Forge and pulses",
        "themeStudio.theme.forge.material": "Steel / copper",
        "themeStudio.theme.forge.text": "Mechanical guides, gears and a directed graph crossed by pulses. The original mobile composition, in the desktop space.",
        "themeStudio.theme.paper.scene": "Page and marginalia",
        "themeStudio.theme.paper.material": "Paper / ink",
        "themeStudio.theme.paper.text": "Fibers, typographic registers and marginal annotations. Light crosses the page without turning it into a decorative grid.",
        "themeStudio.theme.terminal.scene": "Phosphor manuscript",
        "themeStudio.theme.terminal.material": "Phosphor / black",
        "themeStudio.theme.terminal.text": "Streams of glyphs at independent cadence, traces and phosphor. Not a uniform rain: every column has its own rhythm.",
        "themeStudio.theme.aurora.scene": "Magnetic curtains",
        "themeStudio.theme.aurora.material": "Night / cold light",
        "themeStudio.theme.aurora.text": "Vertical rays, magnetic folds and scattered stars. The color comes from the active palette, not from a fixed image.",
        "themeStudio.theme.glacier.scene": "Ice and refraction",
        "themeStudio.theme.glacier.material": "Ice / cobalt",
        "themeStudio.theme.glacier.text": "Translucent facets and directional crevasses: the motion is a slow refraction, not a rotation of particles.",
        "themeStudio.theme.ember.scene": "Convection and embers",
        "themeStudio.theme.ember.material": "Charcoal / ember",
        "themeStudio.theme.ember.text": "Columns of heat, rising embers and diffuse halos. A living background, kept at the edges of the reading area.",
        "themeStudio.theme.atlas.scene": "Relief and routes",
        "themeStudio.theme.atlas.material": "Deep blue / copper",
        "themeStudio.theme.atlas.text": "Contour lines, a cartographic grid and a route between surveyed points. The whole keeps a topographic reading.",
        "themeStudio.theme.noir.scene": "Aperture and raking light",
        "themeStudio.theme.noir.material": "Black / silver",
        "themeStudio.theme.noir.text": "Blades, cuts of light and a photographic aperture. Sharp contrast and few marks, without adding colors to the theme.",
        "themeStudio.theme.signal.scene": "Carriers and acquisition",
        "themeStudio.theme.signal.material": "Graphite / coral",
        "themeStudio.theme.signal.text": "Independent traces, short interruptions and a radar sweep. They are visual motifs, not measurements of the network or the model.",
        "themeStudio.theme.violet.scene": "Parametric orbit",
        "themeStudio.theme.violet.material": "Indigo / amethyst",
        "themeStudio.theme.violet.text": "A continuous curve, non-coinciding orbits and scattered nodes. The detail develops without filling the whole space.",
        "themeStudio.theme.claudius.scene": "Annotated manuscript",
        "themeStudio.theme.claudius.material": "Warm paper / clay",
        "themeStudio.theme.claudius.text": "Typographic masses, editorial brackets and threads of annotation. The rhythm is that of a page reread with care.",
        "themeStudio.theme.basicus.scene": "Modules and propagation",
        "themeStudio.theme.basicus.material": "Neutral / blue",
        "themeStudio.theme.basicus.text": "Geometric modules and a wave crossing their edges. A spatial composition, not a second control panel.",
        "themeStudio.theme.telemetry.scene": "Instruments and logs",
        "themeStudio.theme.telemetry.material": "Graphite / cyan",
        "themeStudio.theme.telemetry.text": "Dials, rulers and thin sliders. The shapes are decorative: they do not represent device statistics.",
